def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            seen.add((r, c))
            stack = [(r, c)]
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x, grid[y][x]))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append(comp)
    motif = max(comps, key=len)
    minr, maxr = min(y for y,x,v in motif), max(y for y,x,v in motif)
    minc, maxc = min(x for y,x,v in motif), max(x for y,x,v in motif)
    ar, ac = (minr+maxr)//2, (minc+maxc)//2
    offsets = [(y-ar,x-ac,v) for y,x,v in motif]
    markers = [(y,x) for comp in comps if comp is not motif for y,x,v in comp]
    out = [row[:] for row in grid]
    for y,x in markers:
        for dy,dx,v in offsets:
            yy,xx=y+dy,x+dx
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx]=v
    return out
